<!--
  GearSwap Atelier · the card of the set shown (card.ts): its head, its versions, the equipment's sixteen slots, the
  line under them, the legend and notes, its figures. The slots and buttons keep the attributes the old page's
  handlers read (events.js data-card / data-slot / data-variant, trial.js data-unslot).

  @file    atelier/src/screens/sets/Card.svelte
  @author  ejouanchicot
-->
<script lang="ts">
  import TrialRow from './TrialRow.svelte';
  import TitleBox from './TitleBox.svelte';
  import WsHead from './WsHead.svelte';
  import WeaponMenu from './WeaponMenu.svelte';
  import StateName from '../../components/StateName.svelte';
  import type {CardView, VerButton, SlotView} from './card';
  import Figures from './Figures.svelte';

  let {view}: {view: CardView} = $props();
</script>

{#snippet ver(b: VerButton)}<button aria-pressed={b.pressed} data-card={view.ci} data-variant={b.i} title={b.title}>{b.label}</button>{/snippet}
{#snippet slot(x: SlotView)}<button class={x.cls} data-card={x.ci} data-slot={x.slot} aria-label={x.aria}>{#if x.reset}<span class="unslot" role="button" tabindex="0" data-unslot={x.slot} data-card={x.ci} title={x.reset.title}>↺</span>{/if}{#if x.lock}<span class="lk" title={x.lock.title}><svg viewBox="0 0 12 12" width="9" height="9" aria-hidden="true"><path d="M3.5 5V3.6a2.5 2.5 0 0 1 5 0V5" fill="none" stroke="currentColor" stroke-width="1.5"/><rect x="2" y="5" width="8" height="6" rx="1.2" fill="currentColor"/></svg></span>{/if}{#if x.empty}<span class="elbl">{x.label}</span>{:else}{@html x.iconHtml}{#if x.aug}<span class="mk">◆</span>{/if}{#if x.rank !== null}<span class="rk">R{x.rank}</span>{/if}{/if}</button>{/snippet}

<article class="detail"><div class="boxh panehead"><h3>{view.pane}</h3></div><header><div class="settop"><TitleBox view={view.title} />{#if view.chips}<div class="hboxes">{#if view.chips.objs.length}<section class="hbox goals" style="--n:{view.chips.objs.length}"><h4>{view.chips.objsHead}</h4><div class="tiles">{#each view.chips.objs as c, i (i)}<div class="tile obj" title={c.of ? c.label + ' : ' + c.value + ' (' + c.of + ')' : undefined}><span class="tl">{c.label}</span><b class="tv {c.value.includes(' · ') ? 'two' : ''}">{#each c.value.split(' · ') as v, j (j)}<span>{v}</span>{/each}</b></div>{/each}</div></section>{/if}{#if view.chips.floors.length}<section class="hbox floors" style="--n:{view.chips.floors.length}"><h4 title={view.chips.floorsTip}>{view.chips.floorsHead}</h4><div class="tiles">{#each view.chips.floors as c, i (i)}<div class="tile {c.ok ? 'ok' : 'ko'}" title={c.tip}><span class="tl">{c.label}</span><b class="tv">{c.value}</b><small class="ts"><i>{c.ok ? '✓' : '✗'}</i> {c.of}</small></div>{/each}</div></section>{/if}</div>{/if}{#if view.versions.k === 'none'}<div class="setvers none"></div>{:else if view.versions.k === 'grid'}<div class="setvers grid"><span class="kicker">{view.versions.label}</span><div class="vergrid" role="group" style="--n:{view.versions.cols.length}"><span></span>{#each view.versions.cols as c (c)}<span class="vh">{c}</span>{/each}{#each view.versions.rows as r, i (i)}<span class="vr">{r.label}</span>{#each r.cells as b, j (j)}{#if b}{@render ver(b)}{:else}<i class="vnone">—</i>{/if}{/each}{/each}</div></div>{:else}<div class="setvers"><span class="kicker">{view.versions.label}</span><div class="verseg" role="group">{#each view.versions.buttons as b, i (i)}{@render ver(b)}{/each}</div></div>{/if}{#if view.ctl}<div class="setctl">{#if view.ctl.k === 'picks'}<section class="hbox wbox"><h4>{view.weapons.label}</h4><button class="wline" data-fold="wfold" aria-expanded={view.weapons.open} title={view.weapons.line}>{#each view.weapons.parts as w, i (i)}<span class="wtag" title={w.cap}>{w.val}</span>{/each}<span class="wcaret">{view.weapons.change} {view.weapons.open ? '▾' : '▸'}</span></button></section>{#if view.weapons.open}<div class="wpicks">{#each view.ctl.menus as m (m.menu.mode)}<div class="wpick"><span class="wslbl" title={m.tip}><StateName name={m.menu.name} /></span><div class="wsval"><WeaponMenu menu={m.menu} title={m.tip} /></div></div>{/each}{#each view.ctl.results as r, i (i)}<div class="wpick"><span class="wslbl">{r.label}</span><div class="wsval"><span class="wauto"><b>{r.name}</b>{' '}<small class="muted" title={r.noteTitle}>{r.note}</small>{#if r.unforce}{' '}<button class="linkbtn" data-unforce={r.unforce}>{r.backLabel}</button>{/if}</span></div></div>{/each}</div>{/if}{:else}<WsHead view={view.ctl.view} />{/if}</div>{/if}</div>{#if view.trial && view.trial.k !== 'idle'}<div class="trybar"><TrialRow row={view.trial.row} /></div>{/if}</header>
    <div class="dbody"><div class="eqcol"><div class="slotcol"><div class="slots">{#each view.slots as x (x.slot)}{@render slot(x)}{/each}</div><button class="btn ghost eqbtn" data-equipset disabled={!view.equip.on} title={view.equip.why}>{view.equip.label}</button><footer>{#each view.footHtml as f, i (i)}<span>{@html f}</span>{/each}</footer><details class="lgfold"><summary title={view.legend.hintHtml.replace(/<[^>]+>/g, '')}>{view.legend.btn}</summary><div class="legend mini lgline">{#each view.legend.items as it, i (i)}<span class={it.off ? 'off' : ''} title={it.tip}>{@html it.markHtml}{it.label}</span>{/each}</div><p class="eqhint">{@html view.legend.hintHtml}</p></details></div><div class="setlua" aria-label={view.lua.head}><code class="lh">{view.lua.head}</code>{#each view.lua.lines as l (l.slot)}<code class="ll {l.tried ? 'tried' : ''}" title={l.full}><span class="lk">{l.slot}</span> = <span class="lv">{l.value}</span>,</code>{/each}{#if view.lua.note}<code class="ln">-- {view.lua.note}</code>{/if}<code class="lh">{view.lua.tail}</code></div>{@html view.wantsHtml}{#if view.notes.fam}<p class="famnote {view.notes.fam.none ? 'none' : ''}">{@html view.notes.fam.textHtml}</p>{/if}{#if view.notes.base}<p class="famnote">{view.notes.base}</p>{/if}</div></div>
    <div class="globals-inline"><Figures view={view.figures} /></div></article>
